use std::env;use regex::Regex;use std::fs;use std::collections::BTreeSet;
fn main(){let re=Regex::new(r"(?i)[a-z0-9._%+-]+\s*(?:@|\[at\]|\(at\))\s*[a-z0-9.-]+\s*(?:\.|\[dot\]|\(dot\))\s*[a-z]{2,}").unwrap();let mut out=BTreeSet::new();for u in env::args().skip(1).filter(|x|x.starts_with("http")){if let Ok(b)=reqwest::blocking::Client::new().get(&u).header("User-Agent","EmailKeywordCrawler/1.0").send().and_then(|r|r.text()){for m in re.find_iter(&b){out.insert(m.as_str().to_lowercase().replace("[at]","@").replace("(at)","@").replace("[dot]",".").replace("(dot)","."));}println!("{{\"event\":\"page\",\"url\":\"{}\",\"emails\":{}}}",u,out.len());}}fs::write("emails.txt",out.into_iter().collect::<Vec<_>>().join("\n")).unwrap();}
